const authorization: AppConfigFactory<AuthorizationConfig> = defineAppConfig(
  (_runtime) => ({
    permissionSets: { rootSet: 'root', defaultSet: 'member' },
    plugins: [defaultAccess(), sharingRules(), restrictionRules()],
  }),

export const visibleDocumentAccess = defineRecordAccess(
  'library.visible',
  (access) =>
    access
      .title(title('library.recordAccess.visible'))
      .description(title('library.recordAccess.visibleDescription'))
      .collections('libraryDocuments')
      .resolver(({ principal }) => {
        if (principal.type !== 'user') return false;
        return buildFilter((filter) =>
          filter.or([
            filter.and([
              filter.boolean('published').isTrue(),
              filter.boolean('confidential').isFalse(),
            ]),
            filter.string('ownerId').eq(principal.id),
          ]),
        );
      }),

async function scopedDocuments(
  context: AuthorizationContext,
  action: 'view' | 'create' | 'edit' | 'delete',
) {
  const policy = await authorization.database.policyFor(
    'libraryDocuments',
    context,
    { resource: LIBRARY_RESOURCE, action },
  );
  return documents().withPolicy(policy);
}

/**
 * Confidential documents are only for their owner and unrestricted administrators. The record access resolver
 * already enforces that base scope, but a sharing rule adds a record on top of it and could accidentally name a
 * confidential document. Apply this check to every read path so a stale or mistaken rule cannot expose one.
 */
async function canReadConfidential(
  context: AuthorizationContext,
  document: LibraryDocumentRow,
): Promise<boolean> {
  if (!document.confidential) return true;
  if (document.ownerId === context.identity.principal.id) return true;
  return (await context.snapshot()).unrestricted;

async setShares(context, id, userIds) {
  const repository = await scopedDocuments(context, 'edit');
  const document = await assertVisible(
    context,
    await repository.findOne({ filter: { id } }),
  );

  const unique = [...new Set(userIds)];
  const key = sharingRuleKey(id);
  if (!unique.length) {
    if (await sharingRules.get(key)) await sharingRules.delete(key);
    return [];
  }
  // An existing stale rule can still be cleared above; confidential documents never gain a new share.
  if (document.confidential) {
    throw new LibraryDocumentNotShareableError();
  }

  // Sharing only widens view access to this one record. It never grants edit or unlocks a document for everyone.
  const rule: SharingRule = {
    key,
    resource: { type: 'composite', id: LIBRARY_RESOURCE },
    actions: [
      {
        action: 'view',
        scopeKey: 'documents',
        selection: { type: 'records', ids: [id] },
      },
    ],
    title: `共享：${document.title}`,
    subjects: unique.map((userId) => ({ type: 'user', id: userId })),
    reason: 'A library document was shared explicitly.',
  };
  if (await sharingRules.get(key)) {
    await sharingRules.update(key, rule);
  } else {
    await sharingRules.create(rule);
  }

async resolveEffectiveScope(principal, resource, action, configs, constraints, requestedFields) {
    // Each grant keeps its own fields and role filters through scope evaluation.
    const branches = await Promise.all(configs.map(async (config) => {
        const positive = await this.compileScopes(principal, resource, action, config.recordAccess ?? []);
        positive.push(...(await this.compileConstraints([...constraints, ...(config.branchConstraints ?? [])].filter((item) => item.effect === 'expand'), principal, resource, action)));
        const branchRestrictions = await this.compileConstraints((config.branchConstraints ?? []).filter((item) => item.effect === 'restrict'), principal, resource, action);
        return {
            config,
            configured: positive.length > 0,
            scope: allScopes([anyScope(positive), ...branchRestrictions]),
        };
    }));
    const restrictions = await this.compileConstraints(constraints.filter((item) => item.effect === 'restrict'), principal, resource, action);
    const fields = resolveDatabaseFields(configs, action);
    const requested = {
        ...requestedFields,
        ...(action === 'read'
            ? { output: resolveActionFields(action, fields, resource) }
            : { input: resolveActionFields(action, fields, resource) }),
    };
    const required = [
        anyScope(branches.map((branch) => branch.scope)),
    ];
    for (const direction of [
        'input',
        'output',
        'filter',
        'sort',
        'group',
    ]) {
        for (const field of requested[direction] ?? []) {
            if (branches.every((branch) => databaseFieldsAllowed({ [direction]: [field] }, resolveDatabaseFields([branch.config], action))))
                continue;
            required.push(anyScope(branches
                .filter((branch) => databaseFieldsAllowed({ [direction]: [field] }, resolveDatabaseFields([branch.config], action)))
                .map((branch) => branch.scope)));
        }
    }
    return {
        scope: allScopes([...required, ...restrictions]),
        configured: branches.some((branch) => branch.configured),
    };

export function sharingRulesPlugin(options) {
    const service = new RuleService({ id: 'sharing-rules', effect: 'expand', bySubject: true, allowAll: false }, requireStore(options.store, 'Sharing Rules'));
    return {
        id: 'sharing-rules',
        authorizationApi: {
            sharingRules: service,
        },
        setup(authz) {
            authz.constraints.add(service);
        },

export function restrictionRulesPlugin(options) {
    const service = new RuleService({
        id: 'restriction-rules',
        effect: 'restrict',
        bySubject: true,
        allowAll: true,
    }, requireStore(options.store, 'Restriction Rules'));
    return {
        id: 'restriction-rules',
        authorizationApi: {
            restrictionRules: service,
        },
        setup(authz) {
            authz.constraints.add(service);
        },
    };

scope(action, scopeKey, selection) {
    if (selection.type === 'all')
        throw new TypeError('A sharing rule cannot select all records');
    this.resource.scope(action, scopeKey);
    return new SharingRuleBuilder(this.resource, {
        ...this.definition,
        actions: appendRuleAction(this.definition.actions, {
            action,
            scopeKey,
            selection,
        }),
    });

export function sharingRules(options = {}) {
    const connection = new DatabaseConnectionHandle('Sharing Rules');
    const plugin = sharingRulesPlugin({
        store: options.store ?? new DatabaseSharingRuleStore(connection.resolve),
    });
    return {
        ...plugin,
        dependencies: ['settings', 'database', 'ui'],
        setup(authz) {
            connection.set(authz.connection);
            plugin.setup?.(authz);
            authz.settings.add({
                id: SHARING_RULES_SETTINGS,
                title: { key: 'resourceTitle', ns: NAMESPACE },
                actions: ['read', 'create', 'update', 'delete'].map((name) => ({
                    name,
                    title: { key: `options.actions.${name}`, ns: APP_NAMESPACE },
                })),
            });
            authz.ui.place({ type: 'settings', id: SHARING_RULES_SETTINGS }, { section: AUTHORIZATION_SETTINGS_SECTION, order: 20 });
            authz.routes.add(SHARING_RULES_PATH, createSharingRulesHandler(authz, plugin.authorizationApi.sharingRules));
        },
    };

export function restrictionRules(options = {}) {
    const connection = new DatabaseConnectionHandle('Restriction Rules');
    const plugin = restrictionRulesPlugin({
        store: options.store ?? new DatabaseRestrictionRuleStore(connection.resolve),
    });
    return {
        ...plugin,
        dependencies: ['settings', 'database', 'ui'],
